 {fields.map(([key,label,choices])=><label key={key}>{label}<select aria-label={label} value={value[key]} onChange={e=>onChange({...value,[key]:Number(e.target.value),...(key==='maxPlayers'?{seekerCount:Math.min(value.seekerCount,Number(e.target.value)-1)}:{})})}>{choices.map(n=><option key={n} value={n} disabled={key==='maxPlayers'&&n<count}>{['maxPlayers','seekerCount'].includes(key)?n+'명':n/60+'분'}</option>)}</select></label>)}
